<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\QuestionLearning;
use App\Application\QuestionLearning\Port\QuestionExplanationContextReaderInterface;use App\Domain\QuestionLearning\Entity\QuestionExplanationExecution;use App\Domain\QuestionLearning\Enum\ExplanationSafetyMode;use App\Domain\QuestionLearning\ValueObject\QuestionExplanationContext;use App\Infrastructure\Persistence\Doctrine\Performance\Entity\AttemptRecord;use App\Infrastructure\Persistence\Doctrine\Performance\Entity\AnswerRecord;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionOptionRecord;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionRecord;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionTaxonomySubjectRecord;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionQualitySignalRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineQuestionExplanationContextReader implements QuestionExplanationContextReaderInterface { public function __construct(private readonly EntityManagerInterface $em) {} public function read(QuestionExplanationExecution $execution):?QuestionExplanationContext { $question=$this->em->find(QuestionRecord::class,$execution->questionId);if(!$question instanceof QuestionRecord||$question->status!=='PUBLISHED')return null;$options=array_map(static fn(QuestionOptionRecord $o):array=>['id'=>$o->id,'label'=>$o->label,'content'=>$o->content],$this->em->createQueryBuilder()->select('o')->from(QuestionOptionRecord::class,'o')->where('o.questionId=:id')->setParameter('id',$question->id)->orderBy('o.sortOrder','ASC')->getQuery()->getResult());$subjects=array_map(static fn(QuestionTaxonomySubjectRecord $s):string=>$s->taxonomySubjectId,$this->em->createQueryBuilder()->select('s')->from(QuestionTaxonomySubjectRecord::class,'s')->where('s.questionId=:id')->setParameter('id',$question->id)->getQuery()->getResult());$selected=null;$correct=null;if($execution->safetyMode===ExplanationSafetyMode::POST_ANSWER&&$execution->attemptId!==null){$attempt=$this->em->find(AttemptRecord::class,$execution->attemptId);if(!$attempt instanceof AttemptRecord||$attempt->userId!==$execution->userId||$attempt->questionId!==$question->id||$attempt->completedAt===null)return null;$answer=$attempt->finalAnswerId===null?null:$this->em->find(AnswerRecord::class,$attempt->finalAnswerId);$selected=$answer instanceof AnswerRecord?$answer->optionId:null;$correct=$selected!==null&&$question->correctOptionId!==null?$selected===$question->correctOptionId:null;}return new QuestionExplanationContext($question->id,$question->statement,$options,$subjects,$execution->safetyMode->value,$selected,$correct,false,($execution->safetyMode===ExplanationSafetyMode::POST_ANSWER?($this->em->find(QuestionQualitySignalRecord::class,$question->id))?->safeMessage:null));}}
